let elaOriginalImage = null;let elaOriginalIsJpeg = false;function elaHandleFile(event){const file = event.target.files[0];if (!file) return;elaOriginalIsJpeg = file.type === "image/jpeg" || file.type === "image/jpg";const reader = new FileReader();reader.onload = (e) =>{const img = new Image();img.onload = () =>{elaOriginalImage = img;document.getElementById("ela-format-note").textContent = elaOriginalIsJpeg ? "// JPEG detected - full ELA signal available" : `// source is ${file.type || "not JPEG"} - ELA is most meaningful on JPEGs with real compression history; results here are approximate`;runEla();};img.src = e.target.result;};reader.readAsDataURL(file);}function computeElaDiff(origData, recompData, amplify){const len = origData.length;const out = new Uint8ClampedArray(len);for (let i = 0;i < len;i += 4){out[i] = Math.abs(origData[i] - recompData[i]) * amplify;out[i + 1] = Math.abs(origData[i + 1] - recompData[i + 1]) * amplify;out[i + 2] = Math.abs(origData[i + 2] - recompData[i + 2]) * amplify;out[i + 3] = 255;}return out;}function runEla(){if (!elaOriginalImage) return;const quality = +document.getElementById("ela-quality").value / 100;const amplify = +document.getElementById("ela-amplify").value;const w = elaOriginalImage.naturalWidth;const h = elaOriginalImage.naturalHeight;const origCanvas = document.createElement("canvas");origCanvas.width = w;origCanvas.height = h;const origCtx = origCanvas.getContext("2d");origCtx.drawImage(elaOriginalImage, 0, 0);const origData = origCtx.getImageData(0, 0, w, h).data;const recompDataUrl = origCanvas.toDataURL("image/jpeg", quality);const recompImg = new Image();recompImg.onload = () =>{const recompCanvas = document.createElement("canvas");recompCanvas.width = w;recompCanvas.height = h;const recompCtx = recompCanvas.getContext("2d");recompCtx.drawImage(recompImg, 0, 0);const recompData = recompCtx.getImageData(0, 0, w, h).data;const diff = computeElaDiff(origData, recompData, amplify);const outCanvas = document.getElementById("ela-output");outCanvas.width = w;outCanvas.height = h;const outCtx = outCanvas.getContext("2d");outCtx.putImageData(new ImageData(diff, w, h), 0, 0);GAMA.say("success");};recompImg.src = recompDataUrl;}function downloadElaOutput(){const canvas = document.getElementById("ela-output");if (!canvas.width) return;const link = document.createElement("a");link.download = "gamayun-ela-output.png";link.href = canvas.toDataURL("image/png");link.click();GAMA.log("Downloaded ELA output");}document.addEventListener("DOMContentLoaded", () =>{const fileInput = document.getElementById("ela-file");if (fileInput){fileInput.addEventListener("change", elaHandleFile);document.getElementById("ela-quality").addEventListener("input", runEla);document.getElementById("ela-amplify").addEventListener("input", runEla);}});